from z3 import *
dice = [[Int(f'd{i}_{j}') for j in range(6)] for i in range(5)]
s = Solver()
for i in range(5):
    for j in range(6):
        s.add(dice[i][j] >= 0, dice[i][j] <= 11)
    for j in range(5):
        s.add(dice[i][j] <= dice[i][j+1])
for i in range(5):
    next_i = (i + 1) % 5
    wins = Sum([If(dice[i][j] > dice[next_i][k], 1, 0) for j in range(6) for k in range(6)])
    s.add(wins > 18)
print(s.check())
if s.check() == sat:
    m = s.model()
    flat = []
    for i in range(5):
        for j in range(6):
            flat.append(m[dice[i][j]].as_long())
    print(flat)

